107	      }
108	      spec[bound] = value;
109	    }
110	    if (spec.minLength !== undefined && spec.maxLength !== undefined && spec.minLength > spec.maxLength) {
111	      throw new Error(`${label}: minLength must not be greater than maxLength`);
112	    }
113	    if (spec.min !== undefined && spec.max !== undefined && spec.min > spec.max) {
