284	      }
285	      right.numericValue = numericValue;
286	    }
287	  } else if (hasValueField) {
288	    if (typeof condition.valueField !== 'string') {
289	      throw new Error(`${where} valueField: path must be a non-empty string`);
290	    }
291	    right = {
292	      kind: 'input', label: 'valueField',
293	      segments: parsePathSegments(condition.valueField, `${where} valueField`),
294	    };
295	  } else {
296	    right = {
297	      kind: 'output', label: 'valueOutputField',
298	      ref: compileOutputReference(condition.valueOutputField, nodes, `${where} valueOutputField`),
299	    };
300	  }
301	
302	  return { kind: 'comparison', operator: condition.operator, left, right };
303	}
