498	// Successor edges and dependency ordering constraints together must stay
499	// acyclic across the whole definition — including branches a run would never
500	// take and nodes the entry cannot reach. The error names a node id chain
501	// whose first and last entries match and whose steps are real edges or
502	// dependency relations.
503	//
504	// The search is an iterative three-color DFS with an explicit frame stack:
505	// a recursive walk over a legal definition tens of thousands of chained
506	// nodes deep would overflow the call stack before producing a result. `path`
507	// holds the gray nodes in DFS order (what a recursive stack would hold) and
508	// `depthById` locates a gray node in it, so a back edge still reports
509	// exactly the cycle segment — never the entry path leading into it.
510	function detectCycles(nodes) {
511	  const adjacency = new Map([...nodes.keys()].map(id => [id, []]));
512	  for (const [id, node] of nodes) {
513	    adjacency.get(id).push(...successorTargets.get(node));
514	    for (const dependency of nodeDependencies.get(node)) {
515	      adjacency.get(dependency).push(id);
516	    }
517	  }
518	  const color = new Map([...nodes.keys()].map(id => [id, 'white']));
519	
520	  for (const root of nodes.keys()) {
521	    if (color.get(root) !== 'white') continue;
522	    color.set(root, 'gray');
523	    const path = [root];
524	    const depthById = new Map([[root, 0]]);
525	    // Each frame is [node id, index of the next outgoing edge to examine].
526	    const frames = [[root, 0]];
527	    while (frames.length > 0) {
528	      const frame = frames[frames.length - 1];
529	      const id = frame[0];
530	      const edges = adjacency.get(id);
