1104	// - collect appends to the caller's own attempt list;
1105	// - onSuccess stores caller-specific success data on the record.
1106	// When a cancellation signal is given, no new attempt starts once it has
1107	// fired — even with a zero retry delay — and a wait in progress ends early;
1108	// an attempt already running is always awaited and its outcome recorded.
1109	// Compensation passes no signal and is therefore never interrupted.
1110	async function runWithRetries({
1111	  retry, signal = null, prepareArgs, invoke, createRecord,
1112	  cloneFailureMessage, sharedMemoryFailureMessage, collect, onSuccess,
1113	}) {
1114	  let lastReason = null;
1115	
1116	  for (let attempt = 1; attempt <= retry.attempts; attempt += 1) {
1117	    if (signal && signal.aborted) {
1118	      return { ok: false, cancelled: true, error: lastReason };
1119	    }
1120	    const args = prepareArgs(attempt);
1121	    const record = createRecord(attempt);
1122	    let returned;
1123	    try {
1124	      returned = await invoke(...args);
1125	    } catch (error) {
1126	      lastReason = describeError(error);
1127	      record.error = lastReason;
1128	    }
1129	
1130	    if (record.error === null && containsSharedMemory(returned)) {
1131	      lastReason = sharedMemoryFailureMessage;
1132	      record.error = lastReason;
1133	    }
1134	
1135	    if (record.error === null) {
1136	      try {
1137	        returned = structuredClone(returned);
1138	      } catch (error) {
1139	        lastReason = cloneFailureMessage;
1140	        record.error = lastReason;
1141	      }
1142	    }
1143	
1144	    if (record.error === null) {
1145	      record.ok = true;
1146	      onSuccess(record, returned);
1147	      collect(record);
1148	      return { ok: true, value: returned };
1149	    }
1150	
1151	    // A cancellation observed while the attempt was in flight keeps the
1152	    // failure record but stops the retry loop: no wait, no next attempt —
1153	    // even when this was the last attempt the run could have made.
1154	    if (signal && signal.aborted) {
1155	      collect(record);
1156	      return { ok: false, cancelled: true, error: lastReason };
1157	    }
1158	
1159	    record.nextDelayMs = attempt < retry.attempts ? retryDelay(retry, attempt) : 0;
1160	    collect(record);
1161	    if (record.nextDelayMs > 0) {
1162	      // A cancellation during the wait ends it immediately; the failed
1163	      // attempt's record keeps its error but no longer promises a delay.
1164	      const interrupted = await sleep(record.nextDelayMs, signal);
1165	      if (interrupted) {
1166	        record.nextDelayMs = 0;
1167	        return { ok: false, cancelled: true, error: lastReason };
1168	      }
1169	    }
1170	  }
1171	
1172	  return { ok: false, error: lastReason };
1173	}
1174	
1175	// Runs one business action with retries. Every invocation receives fresh
1176	// structured clones of the current input and the successful outputs so far;
1177	// the stored success value is a clone independent of any object the
1178	// implementation keeps holding. The cancellation signal applies to this
1179	// loop only — compensation runs without one.
1180	async function runBusinessAction(node, binding, implementation, context, actionAttempts, signal) {
1181	  return runWithRetries({
1182	    retry: binding.retry,
1183	    signal,
1184	    prepareArgs: attempt => [structuredClone(context.input), structuredClone(context.output), node.id, attempt],
1185	    invoke: implementation,
1186	    createRecord: attempt => ({ nodeId: node.id, attempt, ok: false, error: null, nextDelayMs: 0 }),
1187	    cloneFailureMessage: `operation "${binding.name}" returned a value that cannot be structured-cloned`,
1188	    sharedMemoryFailureMessage: `operation "${binding.name}" returned a value that contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this return value is not supported`,
1189	    collect: record => actionAttempts.push(record),
1190	    onSuccess: () => {},
1191	  });
1192	}
1193	
1194	// Runs compensation for one already-succeeded business action. The call gets
1195	// independent structured clones of the input and earlier outputs captured at
1196	// the original action's success moment, the stored return value, the node id
1197	// and a 1-based compensation attempt number. Nothing here can touch the run
1198	// context, a later attempt, another run, or the stored success output.
1199	async function runCompensation(entry, implementation, records) {
1200	  const { nodeId, binding, snapshot } = entry;
1201	  return runWithRetries({
1202	    retry: binding.compensation.retry,
1203	    prepareArgs: attempt => [
1204	      structuredClone(snapshot.input), structuredClone(snapshot.output),
1205	      structuredClone(snapshot.result), nodeId, attempt,
1206	    ],
1207	    invoke: implementation,
1208	    createRecord: attempt => ({
1209	      nodeId, operation: binding.compensation.name, attempt,
1210	      ok: false, error: null, nextDelayMs: 0, result: null,
1211	    }),
1212	    cloneFailureMessage: `compensation "${binding.compensation.name}" returned a value that cannot be structured-cloned`,
1213	    sharedMemoryFailureMessage: `compensation "${binding.compensation.name}" returned a value that contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this return value is not supported`,
1214	    collect: record => records.push(record),
1215	    onSuccess: (record, returned) => { record.result = returned; },
1216	  });
1217	}
1218	
1219	// Undoes successful compensable business actions, most recent first, waiting
1220	// for each compensation to finish before starting the next. A compensation
1221	// that exhausts its retries is recorded as failed but earlier (still-pending)
1222	// actions are compensated regardless; neither the failed compensation nor the
1223	// original business operation is re-run. Compensating a node removes it from
1224	// the pending list exactly once — retried-then-succeeded actions and shared
1225	// join nodes were only recorded once to begin with.
1226	async function compensateRun(state, operations) {
1227	  const records = [];
1228	  let failed = false;
1229	  while (state.compensable.length > 0) {
1230	    const entry = state.compensable.pop();
1231	    const outcome = await runCompensation(entry, operations[entry.binding.compensation.name], records);
1232	    if (!outcome.ok) failed = true;
1233	  }
1234	  return { status: failed ? 'failed' : 'completed', attempts: records };
1235	}
1236	
1237	// Scheduling state shared by the synchronous and asynchronous execution
1238	// loops: activation, completion, dependency gating and the recorded end
1239	// result all behave identically; only business-action handling differs.
1240	function createRunState(nodes, workflow, input) {
1241	  const declarationOrder = [...nodes.values()];
1242	  const declarationIndex = new Map(declarationOrder.map((node, index) => [node.id, index]));
1243	  return {
1244	    trace: [],
1245	    actionAttempts: [],
1246	    context: { input: structuredClone(input), output: {} },
1247	    declarationOrder,
1248	    declarationIndex,
1249	    activated: new Set([workflow.entry]),
1250	    completed: new Set(),
1251	    endReached: false,
1252	    endResult: null,
1253	    // Successful business actions that declared a compensation, in the order
1254	    // they succeeded. Each entry keeps independent snapshots captured at the
1255	    // action's own success moment.
1256	    compensable: [],
1257	  };
1258	}
1259	
1260	function pickReadyNode(state) {
1261	  return state.declarationOrder.find(node =>
1262	    state.activated.has(node.id) && !state.completed.has(node.id)
1263	    && nodeDependencies.get(node).every(dependency => state.completed.has(dependency)));
1264	}
1265	
1266	function blockedResult(state) {
1267	  const waiting = state.declarationOrder.filter(node =>
1268	    state.activated.has(node.id) && !state.completed.has(node.id));
1269	  if (waiting.length === 0) return null;
1270	  return waiting.map(node => ({
1271	    nodeId: node.id,
1272	    missingDependencies: nodeDependencies.get(node)
1273	      .filter(dependency => !state.completed.has(dependency))
1274	      .sort((a, b) => state.declarationIndex.get(a) - state.declarationIndex.get(b)),
1275	  }));
1276	}
1277	
1278	// One shared scheduling step for the synchronous and asynchronous entries.
1279	// pickReadyNode already encodes activation plus dependency gating; this adds
1280	// the rules the two entries used to duplicate:
1281	// - a ready node is recorded in the trace the moment it enters execution, so
1282	//   waiting and never-activated nodes never appear in trace or output;
1283	// - an end node records its result and completes, but never stops the other
1284	//   activated branches — the caller simply loops again;
1285	// - with no ready node left, activated-but-waiting nodes classify the run as
1286	//   "blocked", a visited end node as "completed", and anything else is a
1287	//   structural cycle (validation rejects those before execution).
1288	// The terminal kinds are classifications only: each entry keeps building its
1289	// own result shape (the asynchronous one adds attempt and compensation
1290	// fields) so the public return values are unchanged.
1291	function advanceSchedule(state) {
1292	  const ready = pickReadyNode(state);
1293	  if (!ready) {
1294	    const waiting = blockedResult(state);
1295	    if (waiting) return { kind: 'blocked', waiting };
1296	    if (state.endReached) return { kind: 'completed' };
1297	    throw new Error('workflow did not terminate; a cycle is present');
1298	  }
1299	  state.trace.push({ nodeId: ready.id, type: ready.type });
1300	  if (ready.type === 'end') {
1301	    // Reaching an end node records the result but never stops other
1302	    // activated branches; the run completes once nothing can still run.
1303	    // Snapshot the result at this end node's own execution moment: the
1304	    // recorded value is this run's independent copy, so later mutation of
1305	    // the definition's result (during a wait on another activated branch),
1306	    // of another run's result, or of the returned value cannot reach back
1307	    // here. Validation already guarantees cloneability, so this cannot
1308	    // throw mid-run. An unset or null result stays null; 0, false and ""
1309	    // pass through ?? untouched (only null/undefined default to null).
1310	    state.endReached = true;
1311	    state.endResult = structuredClone(ready.result ?? null);
1312	    state.completed.add(ready.id);
1313	    return { kind: 'end' };
1314	  }
1315	  return { kind: 'run', node: ready };
1316	}
1317	
1318	// Applies a ready non-action node, mutating activation/completion state.
1319	// Returns an early-termination result (invalid_input / invalid_condition)
1320	// or null when execution should continue.
1321	function applyRegularNode(node, state) {
1322	  if (node.type === 'action') {
1323	    // Snapshot the legacy message at this action's own execution moment: the
1324	    // saved output is this run's independent deep copy, so editing nested
1325	    // fields, adding or deleting properties, or changing array members of the
1326	    // returned output never reaches the definition, another run, or an output
1327	    // this action recorded while another activated branch is still waiting.
1328	    // An unset, undefined or null message defaults to action:<node id>;
1329	    // "", 0 and false pass through untouched. Validation already guarantees
1330	    // that an explicit message is structured-cloneable, so this cannot throw
1331	    // mid-run.
1332	    const hasMessage = Object.hasOwn(node, 'message') && node.message !== undefined && node.message !== null;
1333	    const value = hasMessage ? structuredClone(node.message) : `action:${node.id}`;
1334	    setNodeOutput(state.context.output, node.id, value);
1335	  }
1336	  if (node.type === 'form') {
1337	    const compiled = formSchemas.get(node);
1338	    if (compiled) {
1339	      const formResult = processForm(node, state.context.input, compiled);
1340	      if (!formResult.ok) {
1341	        state.context.input = formResult.rollback;
1342	        return { status: 'invalid_input', context: state.context, trace: state.trace, errors: formResult.errors };
1343	      }
1344	    }
1345	  }
1346	  if (node.type === 'condition') {
1347	    const outcome = runCondition(compiledConditions.get(node), state.context.input, state.context.output, node.id);
1348	    if (!outcome.ok) {
1349	      return { status: 'invalid_condition', context: state.context, trace: state.trace, error: outcome.error };
1350	    }
1351	    state.activated.add(outcome.value ? node.then : node.else);
1352	  } else {
1353	    for (const target of successorTargets.get(node)) state.activated.add(target);
1354	  }
1355	  state.completed.add(node.id);
1356	  return null;
1357	}
1358	
1359	// Verifies, before a single node can run, that every business operation and
1360	// every compensation operation in the definition has a function registered —
1361	// including actions on untaken branches and entry-unreachable nodes.
1362	function resolveImplementation(operations, name, nodeId, kind) {
1363	  if (!isUsableObject(operations)
1364	    || !Object.hasOwn(operations, name)
1365	    || typeof operations[name] !== 'function') {
1366	    throw new Error(`action node ${nodeId}: ${kind} operation "${name}" has no function implementation; pass it to executeWorkflowAsync`);
1367	  }
1368	  return operations[name];
1369	}
1370	
1371	function verifyOperations(nodes, operations) {
1372	  for (const node of nodes.values()) {
1373	    const binding = actionBindings.get(node);
1374	    if (binding && binding.name !== null) {
1375	      resolveImplementation(operations, binding.name, node.id, 'business');
1376	    }
1377	    if (binding && binding.compensation !== null) {
1378	      resolveImplementation(operations, binding.compensation.name, node.id, 'compensation');
1379	    }
1380	  }
1381	}
1382	
1383	// The optional fourth argument of executeWorkflowAsync carries an
1384	// AbortSignal as `{ signal }`. Omitting it — or passing undefined, or an
1385	// options object without a signal — keeps the previous behavior; anything
1386	// else is a caller error reported before a single node executes.
1387	function resolveRunSignal(options) {
1388	  if (options === undefined) return null;
1389	  if (!isUsableObject(options)) {
1390	    throw new TypeError('executeWorkflowAsync options must be an object with an optional "signal" AbortSignal');
1391	  }
1392	  if (!Object.hasOwn(options, 'signal') || options.signal === undefined) return null;
1393	  const { signal } = options;
1394	  if (signal instanceof AbortSignal) return signal;
1395	  throw new TypeError('executeWorkflowAsync options.signal must be an AbortSignal');
1396	}
1397	
1398	export function executeWorkflow(workflow, input = {}) {
1399	  const nodes = validateWorkflow(workflow);
1400	  // Business operations are asynchronous: the synchronous entry must refuse
1401	  // a workflow that names any before a single node executes.
1402	  for (const node of nodes.values()) {
1403	    const binding = actionBindings.get(node);
1404	    if (binding && binding.name !== null) {
1405	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
1406	    }
1407	  }
1408	
1409	  const state = createRunState(nodes, workflow, input);
1410	
1411	  for (;;) {
1412	    const step = advanceSchedule(state);
1413	
1414	    if (step.kind === 'blocked') {
1415	      return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes: step.waiting };
1416	    }
1417	    if (step.kind === 'completed') {
1418	      return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
1419	    }
1420	    if (step.kind === 'end') continue;
1421	
1422	    const early = applyRegularNode(step.node, state);
1423	    if (early) return early;
1424	  }
1425	}
1426	
1427	// Attaches compensation results to a failed run. Successful outputs and the
1428	// original terminal status stay untouched; compensation records live on
1429	// their own fields, never in the regular node trace.
1430	async function withCompensation(result, state, operations) {
1431	  const outcome = await compensateRun(state, operations);
1432	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1433	  result.compensationAttempts = outcome.attempts;
1434	  return result;
1435	}
1436	
1437	// The cancelled terminal shape: the run stops where it is, keeps the
1438	// context, trace and attempt records produced so far, and never carries a
1439	// success result. Compensation for already-succeeded actions is attached by
1440	// withCompensation under the usual rules.
1441	function cancelledResult(state) {
1442	  return {
1443	    status: 'cancelled',
1444	    context: state.context,
1445	    trace: state.trace,
1446	    actionAttempts: state.actionAttempts,
1447	  };
1448	}
1449	
1450	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1451	  const signal = resolveRunSignal(options);
1452	  const nodes = validateWorkflow(workflow);
1453	  verifyOperations(nodes, operations);
1454	
1455	  const state = createRunState(nodes, workflow, input);
1456	
1457	  // A signal that is already aborted stops the run before the first node —
1458	  // but only after the definition and the operation registrations above have
1459	  // been checked. Nothing executes and nothing is compensated.
1460	  if (signal && signal.aborted) {
1461	    return withCompensation(cancelledResult(state), state, operations);
1462	  }
1463	
1464	  for (;;) {
1465	    // Once the signal fires, no new regular node runs and no new business
1466	    // action attempt starts; the run ends cancelled with whatever state it
1467	    // reached, even if an end node was already visited on another branch.
1468	    if (signal && signal.aborted) {
1469	      return withCompensation(cancelledResult(state), state, operations);
1470	    }
1471	
1472	    const step = advanceSchedule(state);
1473	
1474	    if (step.kind === 'blocked') {
1475	      // Unmet dependencies end the run; successful compensable actions are
1476	      // rolled back even though an end node may already have been reached.
1477	      return withCompensation({
1478	        status: 'blocked', context: state.context, trace: state.trace,
1479	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1480	      }, state, operations);
1481	    }
1482	    if (step.kind === 'completed') {
1483	      // A completed run never invokes compensation.
1484	      return {
1485	        status: 'completed', result: state.endResult, context: state.context,
1486	        trace: state.trace, actionAttempts: state.actionAttempts,
1487	        compensationStatus: 'not_needed', compensationAttempts: [],
1488	      };
1489	    }
1490	    if (step.kind === 'end') continue;
1491	
1492	    const ready = step.node;
1493	    if (ready.type === 'action') {
1494	      const binding = actionBindings.get(ready);
1495	      if (binding.name !== null) {
1496	        // Nodes execute one at a time in declaration order; awaiting here
1497	        // never lets another node jump ahead.
1498	        const actionResult = await runBusinessAction(
1499	          ready, binding, operations[binding.name], state.context, state.actionAttempts, signal);
1500	        if (!actionResult.ok) {
1501	          if (actionResult.cancelled) {
1502	            // Cancelled while the action was in flight or waiting to retry:
1503	            // the attempt records produced so far stay as they are.
1504	            return withCompensation(cancelledResult(state), state, operations);
1505	          }
1506	          // Retries are exhausted: stop immediately with prior input/output
1507	          // preserved, no output for this node and no successors activated —
1508	          // even if an end node was already reached — then compensate every
1509	          // earlier successful action that asked for it.
1510	          return withCompensation({
1511	            status: 'action_failed', nodeId: ready.id, attempts: binding.retry.attempts,
1512	            error: actionResult.error, context: state.context, trace: state.trace,
1513	            actionAttempts: state.actionAttempts,
1514	          }, state, operations);
1515	        }
1516	        // Capture the compensation snapshots from the state before the new
1517	        // output key lands: the action's own return value is handed to the
1518	        // compensation separately as its third argument.
1519	        const compensationSnapshot = binding.compensation === null ? null : {
1520	          input: structuredClone(state.context.input),
1521	          output: structuredClone(state.context.output),
1522	          result: structuredClone(actionResult.value),
1523	        };
1524	        setNodeOutput(state.context.output, ready.id, actionResult.value);
1525	        if (compensationSnapshot) {
1526	          // Each node completes at most once, so retried-then-successful
1527	          // actions and shared join nodes are scheduled for compensation
1528	          // exactly once.
1529	          state.compensable.push({ nodeId: ready.id, binding, snapshot: compensationSnapshot });
1530	        }
1531	        for (const target of successorTargets.get(ready)) state.activated.add(target);
1532	        state.completed.add(ready.id);
1533	        continue;
1534	      }
1535	    }
1536	
1537	    const early = applyRegularNode(ready, state);
1538	    if (early) {
1539	      early.actionAttempts = state.actionAttempts;
1540	      // A failed form (invalid_input) or failed condition evaluation
1541	      // (invalid_condition) ends normal execution and triggers compensation
1542	      // of the successful business actions that ran earlier.
1543	      return withCompensation(early, state, operations);
1544	    }
1545	  }
1546	}
